 const page=stack.at(-1),fade=useRef(new Animated.Value(1)).current,heroFade=useRef(new Animated.Value(1)).current,requestLock=useRef(false),voiceInput=useRef<any>(null);const {width,height}=useWindowDimensions();const small=width<900;
