 function Feedback(){if(!night)return null;return <EveningFeedback preferShorter={house.memory?.shorter} night={night} mealName={mealById(night.mealId).name} busy={busy} onBack={()=>root('night')} onSave={(feedback:any)=>run(async()=>{const h=await api('nights/'+night.id+'/feedback','POST',feedback);setHouse(h);setNight(h.nights.find((n:any)=>n.id===night.id));root('night');})}/>;}

